use sysinfo::{System, SystemExt, ProcessExt};
use std::time::Duration;

pub struct SystemMonitor {
    system: System,
}

impl SystemMonitor {
    pub fn new() -> Self {
        SystemMonitor {
            system: System::new_all(),
        }
    }

    pub fn update(&mut self) {
        self.system.refresh_all();
    }

    pub fn cpu_usage(&self) -> f32 {
        self.system.cpu_usage().combined().unwrap_or(0.0)
    }

    pub fn memory_usage(&self) -> (u64, u64) {
        let mem = self.system.memory();
        (mem.used(), mem.total())
    }

    pub fn disk_usage(&self) -> Vec<(String, (u64, u64))> {
        self.system.disks().iter()
            .map(|disk| {
                (disk.mount_point().to_string(), (disk.used(), disk.total()))
            })
            .collect()
    }

    pub fn process_count(&self) -> usize {
        self.system.processes().count()
    }

    pub fn get_process_by_pid(&self, pid: u32) -> Option<sysinfo::Process> {
        self.system.processes().find(|p| p.pid() == pid)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_system_monitor() {
        let mut monitor = SystemMonitor::new();
        monitor.update();
        assert!(monitor.cpu_usage() >= 0.0);
        let (used, total) = monitor.memory_usage();
        assert!(used <= total);
    }
}
